import {mountIsotopeLab} from './isotope-lab.js';
import {mountTracerLab} from './tracers.js';
import {defaults,fixed,initialState,observe,advance,presets} from './model.js';
import {CellScene} from './scene.js';
const $=id=>document.getElementById(id),fmt=(v,n=2)=>Number(v).toFixed(n),signed=(v,n=1)=>v<0?'−'+Math.abs(v).toFixed(n):v.toFixed(n);
let params={...defaults},state=initialState(),running=true,speed=5,layer='biology',selected=null,history=[],events=[],lastSample=-1,lastUI=0,simRemainder=0,toastTimer,wasRunning=false,domainStopped=false;
const isotopeLab=mountIsotopeLab(document.getElementById('isotope-lab'));
const tracerLab=mountTracerLab(document.getElementById('tracer-lab'));
const fluxFmt=(v,digits=3)=>Math.abs(v)<.5*10**(-digits)?(0).toFixed(digits):(v>0?'+':'−')+Math.abs(v).toFixed(digits);
const controlSpecs=[
 {key:'respiration',label:'Respiratory capacity',unit:'%',min:0,max:150,step:5,digits:0,ends:['0 · inhibited','150 · enhanced'],target:'mito-controls'},
 {key:'protonLeak',label:'Proton leak',unit:'×',min:.25,max:10,step:.25,digits:2,ends:['0.25 · low leak','10 · uncoupled'],target:'mito-controls'},
 {key:'exchange',label:'ATP/ADP exchange',unit:'×',min:0,max:2,step:.05,digits:2,ends:['0 · blocked','2 · fast exchange'],target:'mito-controls'},
 {key:'reserve',label:'Membrane area reserve',unit:'%',min:0,max:30,step:1,digits:0,ends:['0 · taut','30 · spare area'],target:'mechanics-controls'},
 {key:'glucose',label:'Glucose',unit:'mM',min:0,max:20,step:.1,digits:1,ends:['0 · no fuel','20 · abundant']},
 {key:'oxygen',label:'Dissolved oxygen',unit:'mM',min:0,max:.3,step:.001,digits:3,ends:['0 · anoxic','0.30 · oxygenated']},
 {key:'osmolarity',label:'Bath osmolarity',unit:'mOsm/L',min:180,max:450,step:5,digits:0,ends:['180 · dilute','450 · concentrated']},
 {key:'temperature',label:'Temperature',unit:'°C',min:30,max:42,step:.1,digits:1,ends:['30 · cooler','42 · warmer']},
 {key:'potassium',label:'External potassium',unit:'mM',min:2,max:30,step:.5,digits:1,ends:['2 · low K⁺','30 · high K⁺']},
 {key:'demand',label:'ATP demand',unit:'×',min:.5,max:2,step:.05,digits:2,ends:['0.5 · resting','2.0 · high demand'],advanced:true},
 {key:'stiffness',label:'Stretch stiffness',unit:'mN/m',min:0,max:500,step:10,digits:0,ends:['0 · no elastic resistance','500 · stiffer'],target:'mechanics-controls'},
 {key:'bending',label:'Bending rigidity',unit:'kBT',min:5,max:100,step:5,digits:0,ends:['5 · flexible','100 · rigid'],target:'mechanics-controls'},
 {key:'poreOpening',label:'Manual pore opening',unit:'%',min:0,max:100,step:5,digits:0,ends:['0 · closed','100 · open'],target:'pore-controls'},
 {key:'waterPermeability',label:'Water permeability',unit:'×',min:.25,max:5,step:.25,digits:2,ends:['0.25 · slower','5 · faster'],target:'pore-controls'},
 {key:'blockade',label:'Pump inhibition',unit:'%',min:0,max:100,step:5,digits:0,ends:['0 · uninhibited','100 · blocked'],advanced:true},
];
for(const spec of controlSpecs){const d=document.createElement('div');d.className='control';d.innerHTML=`<div class="control-head"><label for="control-${spec.key}">${spec.label}</label><span class="control-value"><output for="control-${spec.key}" id="value-${spec.key}"></output><small>${spec.unit}</small></span></div><input id="control-${spec.key}" type="range" min="${spec.min}" max="${spec.max}" step="${spec.step}" aria-label="${spec.label} in ${spec.unit}"><div class="range-labels"><span>${spec.ends[0]}</span><span>${spec.ends[1]}</span></div>`;$(spec.target??(spec.advanced?'advanced-controls':'controls')).append(d);
 const input=$(`control-${spec.key}`);input.addEventListener('input',()=>{params[spec.key]=Number(input.value);syncControl(spec);$('preset').value='custom';$('preset-description').textContent='Your experiment. Change one condition at a time to follow cause and effect.';sample(true);renderUI();});input.addEventListener('change',()=>{addEvent(`${spec.label}: ${fmt(params[spec.key],spec.digits)} ${spec.unit}`,spec.key);});
}
function syncControl(spec){const input=$(`control-${spec.key}`);input.value=params[spec.key];input.style.setProperty('--progress',`${100*(params[spec.key]-spec.min)/(spec.max-spec.min)}%`);input.setAttribute('aria-valuetext',`${fmt(params[spec.key],spec.digits)} ${spec.unit}`);$(`value-${spec.key}`).value=fmt(params[spec.key],spec.digits);}
function syncControls(){controlSpecs.forEach(syncControl);$('pore-type').value=String(params.poreType);$('stretch-gating').checked=Boolean(params.stretchGating);}
function changeMembraneSetting(key,value,label){params[key]=value;$('preset').value='custom';$('preset-description').textContent='Your experiment. Follow the link between membrane mechanics, transport, and energy.';addEvent(label,key);renderUI();}
$('pore-type').addEventListener('change',()=>changeMembraneSetting('poreType',Number($('pore-type').value),'Ion pore selectivity changed'));
$('stretch-gating').addEventListener('change',()=>changeMembraneSetting('stretchGating',Number($('stretch-gating').checked),'Stretch-sensitive gating '+($('stretch-gating').checked?'enabled':'disabled')));
for(const preset of presets){const option=document.createElement('option');option.value=preset.id;option.textContent=preset.name;$('preset').append(option);}const custom=document.createElement('option');custom.value='custom';custom.textContent='Custom experiment';custom.disabled=true;$('preset').append(custom);
$('preset').addEventListener('change',()=>applyPreset($('preset').value));
function applyPreset(id){const preset=presets.find(p=>p.id===id);if(!preset)return;domainStopped=false;params={...defaults,...preset.params};state=initialState();tracerLab.reset();isotopeLab.reset();history=[];events=[];lastSample=-1;simRemainder=0;selected=null;running=true;syncControls();$('preset').value=id;$('preset-description').textContent=preset.summary;if(id!=='baseline')addEvent(preset.name,'preset');sample(true);setRunning(true);renderUI();}
function setRunning(value){running=value;$('play-symbol').textContent=value?'Ⅱ':'▶';$('play').setAttribute('aria-label',value?'Pause simulation':'Run simulation');$('running').classList.toggle('paused',!value);$('running').innerHTML=`<i></i>${value?'Running':'Paused'}`;}
$('play').addEventListener('click',()=>setRunning(!running));$('reset').addEventListener('click',()=>{applyPreset('baseline');notify('Reference cell restored. Timeline cleared.');});$('speed').addEventListener('change',()=>speed=Number($('speed').value));
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!/INPUT|SELECT|BUTTON|TEXTAREA/.test(e.target.tagName)&&!$('notes-dialog').open){e.preventDefault();setRunning(!running);}});
function addEvent(label,key){events.push({time:state.time,label,key,params:{...params}});sample(true);}
function sample(force=false){if(!force&&state.time-lastSample<.5)return;const o=observe(state,params);history.push({time:state.time,...o,...params,ATP_amount:state.atp,Na_amount:state.na,K_amount:state.k,Cl_amount:state.cl});lastSample=state.time;}
function notify(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3800);}
const inspectorContent={
 mechanics:{title:'Stretching and bending are different',tag:'PHYSICS ↔ TRANSPORT',symbol:'∿',copy:o=>`Surface stretch produces ${fmt(o.tension)} mN/m tension. The single-mode bending scale is ${fmt(o.rippleNm,1)} nm (displayed 3×). Bending sets ripple size; stretch tension also opposes swelling and can open pores.`},
 pores:{title:'Membrane pores',tag:'BIOLOGY ↔ CHEMISTRY',symbol:'◉',copy:o=>`Actual opening: ${fmt(o.gate*100,1)}%. Ion pore selectivity controls which additional conductances open. Water channels have a separate permeability. These are enlarged schematic pore populations, not literal holes at this scale.`},
 gating:{title:'Stretch-sensitive gates',tag:'PHYSICS → BIOLOGY',symbol:'↗',copy:o=>`Tension ${fmt(o.tension)} mN/m gives a total target opening of ${fmt(o.targetGate*100,1)}%. The gate approaches its target with a 0.8 s time constant. The chosen activation curve is illustrative.`},
 flows:{title:'A balanced cell still has traffic',tag:'BIOLOGY ↔ PHYSICS',symbol:'⇄',copy:o=>`Na⁺ passive flux: ${fluxFmt(o.passiveNa)}; pump flux: ${fluxFmt(-3*o.pump)} mM × V₀/s. Positive is inward. Animation follows these directions and relative magnitudes; fluid flow inside the cell is not resolved.`},
 nucleus:{title:'Nucleus',tag:'BIOLOGY · STRUCTURE',symbol:'◎',copy:'Stores genetic information. In v0.3 it is a visual landmark; gene expression and cell division are future modules.'},
 mitochondria:{title:'Mitochondrion',tag:'BIOLOGY ↔ CHEMISTRY',symbol:'≈',copy:o=>`Matrix ATP: ${fmt(o.matrixATP)} mM; potential: −${fmt(o.mitoPotential,0)} mV. Net ATP delivery: ${fluxFmt(o.atpExchange)} mM × V₀/s. Respiration, proton leak, and ATP exchange connect this compartment to the cytosol.`},
 membrane:{title:'Cell membrane',tag:'BIOLOGY ↔ PHYSICS',symbol:'◌',copy:o=>`Passive ion leaks and the ATP-driven Na⁺/K⁺ pump set ${signed(o.voltage)} mV. Surface tension is ${fmt(o.tension)} mN/m and elastic back pressure is ${fmt(o.laplacePressure)} kPa. Gated pores connect this mechanical state to ion traffic.`},
 er:{title:'Endoplasmic reticulum',tag:'BIOLOGY · STRUCTURE',symbol:'≋',copy:'A membrane network involved in protein and lipid processing. Shown for orientation; ER transport and synthesis are not simulated yet.'},
 golgi:{title:'Golgi apparatus',tag:'BIOLOGY · STRUCTURE',symbol:'≡',copy:'Sorts and packages cellular material. This is a schematic landmark; vesicle trafficking is a future module.'},
 activity:{title:'ATP-supported activity',tag:'ILLUSTRATIVE PROXY',symbol:'↗',copy:o=>`A simple ATP-availability and volume-deviation proxy, now ${fmt(o.activity,0)}% of reference. It is not a viability estimate. See Model & equations for its definition.`},
 atp:{title:'ATP and ADP',tag:'CHEMISTRY ↔ BIOLOGY',symbol:'⋮',copy:o=>`ATP: ${fmt(o.atp)} mM · ADP: ${fmt(o.adp)} mM. Production is ${fmt(o.supply)} mM/s; use is ${fmt(o.use)} mM/s. Their difference changes the ATP pool.`},
 volume:{title:'Water follows osmotic imbalance',tag:'CHEMISTRY ↔ PHYSICS',symbol:'↔',copy:o=>`Inside: ${fmt(o.osmInside,1)} mOsm/L · bath: ${fmt(params.osmolarity,0)} mOsm/L. The current radius is ${fmt(o.radius,1)} µm; a volume change dilutes or concentrates all internal solutes.`},
 voltage:{title:'Membrane potential',tag:'CHEMISTRY ↔ PHYSICS',symbol:'ϟ',copy:o=>`Vₘ: ${signed(o.voltage)} mV. Na⁺ inside: ${fmt(o.na,1)} mM; K⁺ inside: ${fmt(o.k,1)} mM. The model balances passive electrical currents against the pump current.`},
};
function selectOrganelle(name){selected=name;renderInspector(observe(state,params));}
document.querySelectorAll('[data-organelle]').forEach(e=>{e.tabIndex=0;e.setAttribute('role','button');e.setAttribute('aria-label',`Inspect ${e.dataset.organelle}`);e.addEventListener('click',()=>selectOrganelle(e.dataset.organelle));e.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectOrganelle(e.dataset.organelle);}});});document.querySelectorAll('[data-help]').forEach(b=>b.addEventListener('click',()=>selectOrganelle(b.dataset.help)));
let cellScene;try{cellScene=new CellScene($('viewport'),selectOrganelle);}catch(error){console.error('WebGL initialization failed',error);$('webgl-fallback').hidden=false;document.querySelectorAll('.organelle-label').forEach(e=>e.hidden=true);$('cutaway').hidden=true;$('view-reset').hidden=true;}
const layerNames={biology:'CELL ARCHITECTURE',chemistry:'ENERGY & MOLECULES',physics:'FORCES & GRADIENTS'};
const layerKeys={biology:'Organelles · visible pores · membrane transport',chemistry:'Gold: ATP · Blue: ADP · illustrative particles',physics:'Water arrows · reference volume · elastic membrane'};
const layerCopy={biology:'A moving, permeable boundary. Select a pore or organelle; use the membrane lab below to connect mechanics with transport.',chemistry:'Gold particles illustrate ATP availability. ATP supply powers biology; volume changes alter its concentration.',physics:'Volume follows water balance against elastic pressure. Bending rigidity sets the ripple scale; membrane tension can open ion pores.'};
document.querySelectorAll('[data-layer]').forEach(b=>b.addEventListener('click',()=>{layer=b.dataset.layer;selected=null;document.querySelectorAll('[data-layer]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));$('view-name').textContent=layerNames[layer];$('layer-key').innerHTML=`<i class="dot ${layer}-dot"></i>${layerKeys[layer]}`;cellScene?.setLayer(layer);renderInspector(observe(state,params));}));
document.querySelector('.view-tabs').addEventListener('keydown',event=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...document.querySelectorAll('[data-layer]')],index=tabs.indexOf(document.activeElement),next=event.key==='Home'?0:event.key==='End'?2:(index+(event.key==='ArrowRight'?1:2))%3;tabs[next].focus();tabs[next].click();});
let motionEnabled=!matchMedia('(prefers-reduced-motion: reduce)').matches;
function syncMotion(){$('motion-toggle').setAttribute('aria-pressed',String(motionEnabled));$('motion-toggle').classList.toggle('active',motionEnabled);$('motion-toggle').setAttribute('aria-label',motionEnabled?'Pause illustrative motion':'Enable illustrative motion');cellScene?.setMotion(motionEnabled);}
syncMotion();$('motion-toggle').addEventListener('click',()=>{motionEnabled=!motionEnabled;syncMotion();});$('flow-toggle').addEventListener('change',()=>cellScene?.setFlows($('flow-toggle').checked));
$('view-reset').addEventListener('click',()=>{cellScene?.reset();notify('Camera returned to the starting view.');});$('cutaway').addEventListener('click',()=>{const cut=$('cutaway').getAttribute('aria-pressed')!=='true';$('cutaway').setAttribute('aria-pressed',String(cut));$('cutaway').classList.toggle('active',cut);cellScene?.setCutaway(cut);});
function renderInspector(o){const c=selected?inspectorContent[selected]:null;$('inspector-title').textContent=c?c.title:layer==='biology'?'The cell, as a connected system':layer==='chemistry'?'Chemical energy, made visible':'A balance of ions and water';$('inspector-tag').textContent=c?c.tag:'EXPLORE';$('inspector-symbol').textContent=c?c.symbol:layer==='biology'?'◎':layer==='chemistry'?'⋮':'↔';$('inspector-copy').textContent=c?(typeof c.copy==='function'?c.copy(o):c.copy):layerCopy[layer];}
function renderUI(){const o=observe(state,params);$('activity').textContent=fmt(o.activity,0);$('activity-bar').style.width=`${Math.max(0,Math.min(100,o.activity))}%`;$('pump').textContent=fmt(o.pumpPercent,0)+'%';$('atp').textContent=fmt(o.atp);$('supply').textContent=fmt(o.supply);$('volume').textContent=fmt(o.volume);$('voltage').textContent=signed(o.voltage);$('pressure').textContent=signed(o.pressure);$('water-flow').textContent=Math.abs(o.waterRate)<.00008?'In balance':o.waterRate>0?'Inward → swelling':'Outward → shrinking';const ox=o.supply>1e-12?100*o.oxidative/o.supply:0,gly=o.supply>1e-12?100-ox:0;$('ox-bar').style.width=ox+'%';$('gly-bar').style.width=gly+'%';$('ox-percent').textContent=fmt(ox,0)+'%';$('gly-percent').textContent=fmt(gly,0)+'%';$('time').textContent=`${Math.floor(state.time/60).toString().padStart(2,'0')}:${Math.floor(state.time%60).toString().padStart(2,'0')}`;
 $('chart-atp-value').textContent=fmt(o[chartSpecs[0].key]);$('chart-voltage-value').textContent=signed(o.voltage);$('chart-volume-value').textContent=fmt(o[chartSpecs[2].key],chartSpecs[2].displayDigits??2);renderInspector(o);renderStatus(o);renderMembrane(o);drawCharts();drawSparkline();}
function renderMembrane(o){$('cyto-atp').textContent=fmt(o.atp);$('matrix-atp').textContent=fmt(o.matrixATP);$('matrix-adp').textContent=fmt(o.matrixADP);$('mito-voltage').textContent='−'+fmt(o.mitoPotential,1);$('resp-drive').textContent=fmt(o.respiratoryDrive);$('atp-delivery').textContent=fluxFmt(o.atpExchange)+' mM × V₀/s';$('synthase-flux').textContent=fmt(o.synthase,3)+' mM × V₀/s';$('tension').textContent=fmt(o.tension);$('area-strain').textContent=fmt(o.areaStrain*100,1);$('ripple').textContent=fmt(o.rippleNm,1);$('gate-percent').textContent=fmt(o.gate*100,0)+'%';$('gate-bar').style.width=(o.gate*100)+'%';$('flow-na').textContent=fluxFmt(o.passiveNa);$('flow-k').textContent=fluxFmt(o.passiveK);$('flow-cl').textContent=fluxFmt(o.passiveCl);$('pump-na').textContent=fluxFmt(-3*o.pump);$('pump-k').textContent=fluxFmt(2*o.pump);$('flow-water').textContent=fluxFmt(o.waterRate,4);$('elastic-pressure').textContent=fmt(o.laplacePressure);document.querySelector('[aria-label="Membrane mechanics and transport laboratory"]').classList.toggle('high-tension',o.tension>10);}
function renderStatus(o){let title='Near reference state',copy='Energy, ions, and water are in balance.',warning=false;
 if(domainStopped){title='Model boundary reached';copy='This state is outside v0.3’s operating range. Reset to start another experiment.';warning=true;}
 else if(o.tension>10){title='High surface tension',copy='This effective shell has no rupture model. Treat large stretches as an exploration outside intact-bilayer behavior.',warning=true;}
 else if(params.blockade>80){title='Pump inhibited',copy='Passive leaks gradually redistribute ions. Watch voltage and volume over minutes.',warning=true;}
 else if(o.atp<1){title='ATP supply constrained',copy='Lower ATP availability reduces energy-supported activity and pumping.',warning=true;}
 else if(o.volume>1.12){title='Cell has swollen',copy='Water influx increases volume and dilutes intracellular solutes.',warning=true;}
 else if(o.volume<.88){title='Cell has shrunk',copy='Water efflux decreases volume and concentrates intracellular solutes.',warning=true;}
 else if(o.voltage>-50){title='Membrane depolarized',copy='The inside is less negative than the reference state.',warning=true;}
 else if(Math.abs(o.waterRate)>.0005){title='Water is redistributing',copy=o.waterRate>0?'The bath is more dilute; water moves inward.':'The bath is more concentrated; water moves outward.';}
 else if(o.atp<2.6){title='Energy state is adapting',copy='ATP production and consumption are finding a new balance.';}
 $('status-title').textContent=title;$('status-copy').textContent=copy;$('status-card').classList.toggle('warning',warning);
 $('connection-title').textContent=params.stretchGating&&o.gate>.1?'Swelling → tension → pore opening → ion traffic.':params.oxygen<.01?'Less oxygen → less ATP → weaker pumping.':Math.abs(params.osmolarity-300)>30?'Osmolarity changes volume. Volume changes chemistry.':params.potassium>12?'Ion gradients set electrical behavior.':params.blockade>50?'Active transport links ATP to physical balance.':'A cell is a conversation between systems.';
}
const chartSpecs=[{id:'chart-atp',key:'atp',color:'#c6a15e',baseline:3,min:0,max:5.5,digits:1},{id:'chart-voltage',key:'voltage',color:'#809eb8',baseline:-70,min:-100,max:-20,digits:0},{id:'chart-volume',key:'volume',color:'#90a26d',baseline:1,min:.6,max:1.5,digits:1}];
const mechanicsTraces={volume:{key:'volume',color:'#90a26d',baseline:1,min:.6,max:1.5,digits:1,displayDigits:2,unit:'× reference',name:'Cell volume'},tension:{key:'tension',color:'#6c9a98',baseline:0,min:0,max:10,digits:1,displayDigits:2,unit:'mN/m',name:'Membrane tension'},gate:{key:'gate',color:'#8aa16f',baseline:0,min:0,max:1,digits:1,displayDigits:2,unit:'fraction open',name:'Pore opening'}};
$('mechanics-trace').addEventListener('change',()=>{const trace=mechanicsTraces[$('mechanics-trace').value];Object.assign(chartSpecs[2],trace);$('mechanics-trace-unit').textContent=trace.unit;$('chart-volume').setAttribute('aria-label',trace.name+' over simulated time');renderUI();});
const energyTraces={atp:{key:'atp',baseline:3,min:0,max:5.5,digits:1,unit:'mM'},matrixATP:{key:'matrixATP',baseline:4,min:0,max:6,digits:1,unit:'mM'},mitoPotential:{key:'mitoPotential',baseline:150,min:0,max:220,digits:0,unit:'mV · magnitude'}};
$('energy-trace').addEventListener('change',()=>{const t=energyTraces[$('energy-trace').value];Object.assign(chartSpecs[0],t);$('energy-trace-unit').textContent=t.unit;$('chart-atp').setAttribute('aria-label',$('energy-trace').selectedOptions[0].text+' over simulated time');renderUI();});
function drawCharts(){const end=Math.max(120,state.time),start=Math.max(0,end-120);$('history-range').textContent=`Showing ${Math.floor(start)}–${Math.floor(end)} simulated seconds`;for(const spec of chartSpecs)drawChart(spec,start,end);}
function drawChart(spec,start,end){const canvas=$(spec.id),rect=canvas.getBoundingClientRect();if(!rect.width)return;const dpr=Math.min(devicePixelRatio,2);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const w=rect.width,h=rect.height,left=30,right=5,top=10,bottom=20,pw=w-left-right,ph=h-top-bottom;ctx.clearRect(0,0,w,h);let data=history.filter(d=>d.time>=start-.6);const min=Math.min(spec.min,...data.map(d=>d[spec.key]-(spec.max-spec.min)*.04)),max=Math.max(spec.max,...data.map(d=>d[spec.key]+(spec.max-spec.min)*.04));const yy=v=>top+(max-v)/(max-min)*ph,xx=t=>left+(t-start)/(end-start)*pw;ctx.font='7px system-ui';ctx.lineWidth=.6;ctx.textAlign='right';ctx.fillStyle='#abb49f';
 for(let i=0;i<3;i++){const val=min+(max-min)*i/2,y=yy(val);ctx.strokeStyle='#e9eee1';ctx.setLineDash([]);ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillText(val.toFixed(spec.digits),left-7,y+2.5);}
 ctx.textAlign='center';for(let i=0;i<3;i++){const t=start+(end-start)*i/2;ctx.fillText(`${Math.floor(t)}s`,Math.max(14,Math.min(w-13,xx(t))),h-4);}
 ctx.save();ctx.beginPath();ctx.rect(left,top,pw,ph);ctx.clip();if($('baseline').checked){ctx.strokeStyle='#ad824c';ctx.lineWidth=1.5;ctx.setLineDash([5,4]);ctx.beginPath();ctx.moveTo(left,yy(spec.baseline));ctx.lineTo(w-right,yy(spec.baseline));ctx.stroke();}
 for(const e of events){if(e.time<start||e.time>end)continue;ctx.strokeStyle='#c9d1bd';ctx.setLineDash([2,3]);ctx.beginPath();ctx.moveTo(xx(e.time),top);ctx.lineTo(xx(e.time),h-bottom);ctx.stroke();}
 if(data.length){const last=observe(state,params);data=[...data,{time:state.time,...last}];ctx.setLineDash([]);ctx.beginPath();data.forEach((d,i)=>{if(i===0)ctx.moveTo(xx(d.time),yy(d[spec.key]));else ctx.lineTo(xx(d.time),yy(d[spec.key]));});ctx.lineTo(xx(state.time),h-bottom);ctx.lineTo(xx(data[0].time),h-bottom);ctx.closePath();const gradient=ctx.createLinearGradient(0,top,0,h-bottom);gradient.addColorStop(0,spec.color+'22');gradient.addColorStop(1,spec.color+'02');ctx.fillStyle=gradient;ctx.fill();ctx.beginPath();data.forEach((d,i)=>{if(i===0)ctx.moveTo(xx(d.time),yy(d[spec.key]));else ctx.lineTo(xx(d.time),yy(d[spec.key]));});ctx.strokeStyle=spec.color;ctx.lineWidth=1.7;ctx.stroke();ctx.beginPath();ctx.arc(xx(state.time),yy(last[spec.key]),2.5,0,Math.PI*2);ctx.fillStyle=spec.color;ctx.fill();}ctx.restore();}
function drawSparkline(){const data=history.slice(-100);if(!data.length)return;const min=Math.min(0,...data.map(d=>d.atp)),max=Math.max(4,...data.map(d=>d.atp));$('sparkline').querySelector('path').setAttribute('d',data.map((d,i)=>`${i?'L':'M'}${(i/Math.max(1,data.length-1)*78+1).toFixed(1)},${(27-(d.atp-min)/(max-min)*24).toFixed(1)}`).join(' '));}
$('baseline').addEventListener('change',drawCharts);new ResizeObserver(drawCharts).observe($('chart-atp'));
$('export').addEventListener('click',()=>{sample(true);const columns=['time','glucose','oxygen','osmolarity','temperature','potassium','demand','blockade','atp','adp','supply','use','glycolysis','oxidative','na','k','cl','pump','pumpPercent','voltage','volume','radius','osmInside','osmDelta','pressure','waterRate','activity','ATP_amount','Na_amount','K_amount','Cl_amount','stiffness','bending','poreOpening','poreType','waterPermeability','stretchGating','gate','tension','areaStrain','laplacePressure','netPressure','rippleNm','passiveNa','passiveK','passiveCl','poreFluxNa','poreFluxK','poreFluxCl','matrixATP','matrixADP','mitoPotential','respiratoryDrive','synthase','atpExchange','respiration','protonLeak','exchange','reserve'];const headers=['time_s','bath_glucose_mM','bath_oxygen_mM','bath_osmolarity_mOsm_L','temperature_C','bath_potassium_mM','ATP_demand_relative','pump_blockade_percent','ATP_mM','ADP_mM','ATP_supply_mM_s','ATP_use_mM_s','glycolytic_ATP_mM_s','oxidative_ATP_mM_s','Na_in_mM','K_in_mM','Cl_in_mM','pump_mM_V0_s','pump_percent_reference','membrane_mV','volume_V0','radius_um','osm_inside_mOsm_L','osm_delta_mOsm_L','osmotic_pressure_delta_kPa','water_rate_V0_s','activity_proxy_percent','ATP_amount_mM_V0','Na_amount_mM_V0','K_amount_mM_V0','Cl_amount_mM_V0','surface_stiffness_mN_m','bending_kBT','manual_pore_open_percent','pore_type_0_broad_1_Na_2_K','water_permeability_relative','stretch_gating_enabled','pore_open_fraction','tension_mN_m','area_strain_fraction','elastic_pressure_kPa','net_water_pressure_kPa','single_mode_ripple_nm','passive_Na_inward_mM_V0_s','passive_K_inward_mM_V0_s','passive_Cl_inward_mM_V0_s','pore_Na_inward_mM_V0_s','pore_K_inward_mM_V0_s','pore_Cl_inward_mM_V0_s','matrix_ATP_mM','matrix_ADP_mM','matrix_potential_magnitude_mV','respiration_drive_relative','ATP_synthesis_mM_V0_s','ATP_exchange_to_cytosol_mM_V0_s','respiratory_capacity_percent','proton_leak_relative','ATP_exchange_relative','membrane_area_reserve_percent'];const csv=[headers.join(','),...history.map(d=>columns.map(k=>Number(d[k]).toPrecision(8)).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='cellula-experiment.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(`Exported ${history.length.toLocaleString()} samples with conditions and model outputs.`);});
const dialog=$('notes-dialog');function openNotes(){wasRunning=running;setRunning(false);dialog.showModal();}function closeNotes(){dialog.close();}for(const id of ['model-notes','limitations'])$(id).addEventListener('click',openNotes);dialog.querySelector('.close-dialog').addEventListener('click',closeNotes);dialog.addEventListener('close',()=>{if(wasRunning&&!domainStopped)setRunning(true);});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeNotes();}});
const tableRows=[['Reference bath','5 mM glucose · 0.200 mM O₂ · 300 mOsm/L · 37 °C'],['Reference intracellular ions','Na⁺ 15 · K⁺ 135 · Cl⁻ '+fmt(initialState().cl,4)+' mM'],['Reference energy','ATP 3 mM · ADP 2 mM · ATP supply 0.566843 mM/s (cytosol)'],['Impermeant pool X',fmt(fixed.impermeant,5)+' mM × V₀; mean charge −1'],['Reference pump P₀','0.025 mM × V₀/s'],['Membrane mechanics','KA = 80 mN/m · κ = 20 kBT · 10% area reserve · no initial tension'],['Pore population','0.006 mM × V₀/(mV·s) at full opening · τ = 0.8 s'],['Stretch gating','Half-activation at 2 mN/m · Hill exponent 2'],['gNa / gK / gCl',[fixed.gNa,fixed.gK,fixed.gCl].map(v=>v.toPrecision(5)).join(' / ')+' mM × V₀/(mV·s)'],['Water coefficient','0.18 V₀/s per normalized osmotic difference'],['Energy constants','Km glucose 1 mM · Km O₂ 0.01 mM · Km ADP 0.5 mM']];$('parameter-table').innerHTML='<table><thead><tr><th>Parameter</th><th>Illustrative value</th></tr></thead><tbody>'+tableRows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')+'</tbody></table>';
// Debug surface exposes model state only, for reproducible QA and future iteration.
window.cellula={getState:()=>({...state}),getParameters:()=>({...params}),getObservation:()=>observe(state,params),getHistory:()=>history.map(d=>({...d})),getEvents:()=>events.map(d=>({...d})),applyPreset,pause:()=>setRunning(false)};
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.12,Math.max(0,(now-(frame.last??now))/1000));frame.last=now;if(running&&!document.hidden){simRemainder+=dt*speed;while(simRemainder>=.04){const step=advance(state,params,.04);if(!step.valid){domainStopped=true;setRunning(false);simRemainder=0;notify('Model boundary reached. Reset the cell to start a new experiment.');break;}state=step.state;tracerLab.step(.04);isotopeLab.step(.04,state.volume,params.oxygen);simRemainder-=.04;sample();}}if(now-lastUI>120){renderUI();tracerLab.render();renderReference();isotopeLab.render();lastUI=now;}if(cellScene){const visual=isotopeLab.visual();cellScene.setIsotopeOverlay(visual);$('isotope-view-label').textContent=visual.enabled?visual.label+' · dark = heavier isotope, light = lighter · composition markers, not trajectories':'';cellScene.update(observe(state,params),state.time,dt);}}
syncControls();$('preset').value='baseline';$('preset-description').textContent=presets[0].summary;sample(true);setRunning(true);renderUI();requestAnimationFrame(frame);

function renderReference(){const o=observe(state,params),r=observe(initialState(),defaults);$('reference-values').innerHTML=[['ATP',o.atp,r.atp,'mM'],['Volume',o.volume,r.volume,'V₀'],['Voltage',o.voltage,r.voltage,'mV']].map(([n,v,b,u])=>`<span><b>${n}</b> ${fmt(v)} / reference ${fmt(b)} ${u} · Δ ${signed(v-b,2)}</span>`).join('');}
$('restore-reference').addEventListener('click',()=>{params={...defaults};syncControls();isotopeLab.restore();$('preset').value='custom';$('preset-description').textContent='Reference controls restored; current state retained to observe recovery.';addEvent('Reference conditions restored; state retained','reference');renderReference();renderUI();notify(domainStopped?'Controls restored. Model boundary reached: use Reset to restart.':'Reference controls restored. State and history preserved.');});

document.addEventListener('cellula-comparison-start',()=>{if(domainStopped){notify('Cell model boundary reached. Reset the cell before running a new comparison.');return;}setRunning(true);});
